void LQR_K_GetInterpolated(float leg_length_m, K_Fixed_Leg_t output) {
    if (!isfinite(leg_length_m)) leg_length_m = LQR_K_SCHEDULE_MIN_LENGTH_M;
    if (leg_length_m <= LQR_K_Schedule[0].leg_length_m) {
        for (uint32_t row = 0; row < 4U; ++row)
            for (uint32_t col = 0; col < 10U; ++col) output[row][col] = LQR_K_Schedule[0].gain[row][col];
        return;
    }
    if (leg_length_m >= LQR_K_Schedule[LQR_K_SCHEDULE_COUNT - 1U].leg_length_m) {
        for (uint32_t row = 0; row < 4U; ++row)
            for (uint32_t col = 0; col < 10U; ++col) output[row][col] = LQR_K_Schedule[LQR_K_SCHEDULE_COUNT - 1U].gain[row][col];
        return;
    }
    uint32_t lower = (uint32_t)((leg_length_m - LQR_K_SCHEDULE_MIN_LENGTH_M) / LQR_K_SCHEDULE_STEP_M);
    if (lower >= LQR_K_SCHEDULE_COUNT - 1U) lower = LQR_K_SCHEDULE_COUNT - 2U;
    const float lo = LQR_K_Schedule[lower].leg_length_m;
    const float hi = LQR_K_Schedule[lower + 1U].leg_length_m;
    const float ratio = (leg_length_m - lo) / (hi - lo);
    for (uint32_t row = 0; row < 4U; ++row)
        for (uint32_t col = 0; col < 10U; ++col)
            output[row][col] = LQR_K_Schedule[lower].gain[row][col] +
                (LQR_K_Schedule[lower + 1U].gain[row][col] - LQR_K_Schedule[lower].gain[row][col]) * ratio;
}
